function M.insert()
  require("emojis.picker").insert()
end

function M.overlay(mode)
  require("emojis.overlay").open(mode)
end

function M.cascade_groups(set)
  local sets = require("emojis.config").checkbox_sets(set)
  return vim.deepcopy(sets)
end

function M.ops()
  return require("emojis.core.ops")
end

function M.setup(cfg)
  require("emojis.commands").register(cfg)
end

function M.replace(lines, names)
  names = names or {}
  return map_spans(lines, function(glyph)
    local cp = patterns.codepoint(glyph)
    return names[cp] or string.format(":U+%04X:", cp)
  end)
end

function M.wrap(lines, prefix, suffix)
  prefix, suffix = prefix or "", suffix or ""
  return map_spans(lines, function(glyph)
    return prefix .. glyph .. suffix
  end)
end

local function encode(cp)
  if cp < 0x80 then
    return { cp }
  elseif cp < 0x800 then
    return { 0xC0 + math.floor(cp / 0x40), 0x80 + (cp % 0x40) }
  elseif cp < 0x10000 then
    return {
      0xE0 + math.floor(cp / 0x1000),
      0x80 + (math.floor(cp / 0x40) % 0x40),
      0x80 + (cp % 0x40),
    }
  else
    return {
      0xF0 + math.floor(cp / 0x40000),
      0x80 + (math.floor(cp / 0x1000) % 0x40),
      0x80 + (math.floor(cp / 0x40) % 0x40),
      0x80 + (cp % 0x40),
    }
  end
end

local function encode_str(bytes)
  if #bytes == 1 then
    return sc(bytes[1])
  elseif #bytes == 2 then
    return sc(bytes[1], bytes[2])
  elseif #bytes == 3 then
    return sc(bytes[1], bytes[2], bytes[3])
  else
    return sc(bytes[1], bytes[2], bytes[3], bytes[4])
  end
end

function M.encode(cp)
  return encode_str(encode(cp))
end

function M.codepoint(glyph)
  return require("emojis.util.lib").utf8_decode(glyph, 1) or (glyph:byte(1) or 0)
end

function M.close()
  close_then()
end

function M.is_open()
  return state ~= nil and state.surf:is_valid()
end

function M.reset()
  _store = {}
  save()
end

function M._invalidate()
  _store = nil
end

function M.info(msg)
  lib.notifier().info(msg)
end

function M.warn(msg)
  lib.notifier().warn(msg)
end

function M.error(msg)
  lib.notifier().error(msg)
end

local function buf_ok(buf)
  return type(buf) == "number" and api.nvim_buf_is_valid(buf)
end

function M.first()
  goto_emoji(0, 1, false)
end
